function rowFields(row){return Object.fromEntries(row.fields.map(({name,value_canonical_json})=>[name,JSON.parse(value_canonical_json)]));}
function allRows(ledger){return [...ledger.protected_external_records,...ledger.tables.flatMap(({rows})=>rows)];}
function rowsOf(ledger,type){return allRows(ledger).filter((row)=>row.record_type===type);}
function withoutOwnDigest(value,field){const copy=structuredClone(value);delete copy[field];return copy;}
function assertRecordDigests(ledger,label){
  for(const row of allRows(ledger)){
    assert.deepEqual(row.fields.map((x)=>x.name),[...row.fields.map((x)=>x.name)].sort(byCodeUnit),`${label} ${row.primary_key} field order`);
    assert.equal(new Set(row.fields.map((x)=>x.name)).size,row.fields.length,`${label} ${row.primary_key} duplicate field`);
    for(const field of row.fields)assert.equal(canonical(JSON.parse(field.value_canonical_json)),field.value_canonical_json,`${label} ${row.primary_key}.${field.name} value is not CJ`);
  }
}
function assertResponseDigests(response,label){
  const bytes=Buffer.from(response.bytes_hex,'hex');
  assert.equal(bytes.length,response.byte_length,`${label} response byte length`);
  assert.equal(response.digest,digest(bytes),`${label} response byte digest`);
  if(response.kind==='none'){assert.equal(bytes.length,0,`${label} none response must be empty`);return null;}
  const decoded=JSON.parse(bytes.toString('utf8'));
  assert.equal(canonical(decoded),bytes.toString('utf8'),`${label} response is not exact CJ`);
  const ownDigest=response.kind==='error'?'error_digest':'result_digest';
  assert.equal(decoded[ownDigest],digest(Buffer.from(canonical(withoutOwnDigest(decoded,ownDigest)),'utf8')),`${label} embedded ${ownDigest}`);
  return decoded;
}
const oracleCounterPreimage=(oracles)=>({entropy_calls:oracles.entropy.calls,credential_calls:oracles.credentials.calls,failure_calls:oracles.failures.calls,crash_calls:oracles.crashes.calls});
