  const rateProofEntry=vector.initial_state.oracles.digest_outputs.find((x)=>x.name==='q23_rate_transition'),rateProof=rateProofEntry?JSON.parse(rateProofEntry.canonical_value):null,transitions=rateProof?.transitions??[],advance=transitions.length?Math.max(...transitions.map((x)=>x.effective_elapsed_ms)):vector.schedule.length,initial=vector.initial_state.clock_state,wallAdvance=transitions.length?transitions[0].observed_wall_delta_ms:advance;
