test('operation, schema-ref, tool, error and vector inventories are exact',async()=>{
  const op=await json('operation-inventory.json'),opSchema=await json('operation-inventory.schema.json'),tools=await json('tool-registry.json'),toolSchema=await json('tool-registry.schema.json'),errors=await json('error-fixture.json'),mcp=await json('mcp-conformance-fixture.json'),migration=await json('migration-fixture.json'),security=await json('security-fixture.json');
  assert.equal(op.operations.length,32);assert.deepEqual(op.authority_class_counts,{LOCAL_BOOTSTRAP:1,OWNER_ONLY:24,PUBLIC_AUTHENTICATED:7});assert.equal(Object.keys(opSchema.$defs).length,56);
  const publicRefs=op.operations.filter((x)=>x.authority==='PUBLIC_AUTHENTICATED').flatMap((x)=>[x.request_schema_ref,x.result_schema_ref]);assert.equal(publicRefs.length,14);assert.ok(publicRefs.every((x)=>x.startsWith('tool-registry.schema.json#/$defs/')));
  assert.equal(tools.required_tools.length,7);assert.equal(tools.deferred_tools.length,16);assert.equal(Object.keys(toolSchema.$defs).length,58);assert.equal(new Set(tools.required_tools.map((x)=>x.name)).size,7);
  assert.equal(errors.error_count,53);assert.equal(errors.errors.length,53);assert.equal(errors.alias_count,34);assert.equal(Object.keys(errors.interface_aliases).length,34);assert.equal(new Set(errors.errors.map((x)=>x.code)).size,53);
  assert.equal(mcp.vectors.length,67);assert.equal(new Set(mcp.vectors.map((x)=>x.id)).size,67);assert.equal(migration.vectors.length,89);assert.equal(security.vectors.length,205);
});

test('every canonical fixture request validates against its declared exact operation schema',async()=>{
  const inventory=await json('operation-inventory.json'),ajv=new Ajv2020({strict:true,allErrors:true,allowUnionTypes:true});addFormats(ajv);for(const name of ['operation-inventory.schema.json','tool-registry.schema.json'])ajv.addSchema(await json(name),name);const operations=new Map(inventory.operations.map((x)=>[x.operation,x.request_schema_ref]));assert.equal(operations.size,32);
  const intentionalValueNegatives=new Set(['CURSOR-ALIAS-001','CURSOR-ALIAS-002']),{vectors}=await fixtureCoordinate();for(const vector of vectors)if(vector.stimulus.kind==='canonical_request'){const ref=operations.get(vector.stimulus.operation);assert.ok(ref,`${vector.id} undeclared operation ${vector.stimulus.operation}`);const validate=ajv.getSchema(ref),bytes=Buffer.from(vector.stimulus.request_bytes_hex,'hex'),text=bytes.toString('utf8'),value=JSON.parse(text);assert.equal(canonical(value),text,`${vector.id} canonical request bytes`);assert.ok(validate,`${vector.id} missing request schema ${ref}`);assert.equal(validate(value),!intentionalValueNegatives.has(vector.id),`${vector.id} ${vector.stimulus.operation}: ${ajv.errorsText(validate.errors)}`);}assert.equal(vectors.filter((x)=>intentionalValueNegatives.has(x.id)&&x.stimulus.kind==='canonical_request').length,2,'cursor aliases must remain canonical value-negative requests');
});

