test('fixture wire bytes and every exposed digest are independently reproducible',async()=>{
  const {vectors}=await fixtureCoordinate();
  for(const vector of vectors){
    const requestBytes=Buffer.from(vector.stimulus.request_bytes_hex,'hex');
    assert.equal(requestBytes.length,vector.stimulus.request_byte_length,`${vector.id} request byte length`);
    assert.equal(vector.stimulus.request_digest,digest(requestBytes),`${vector.id} request byte digest`);
    assert.notEqual(vector.stimulus.operation,'fixture.case',`${vector.id} generic fixture operation`);
    assert.ok(['canonical_request','raw_transport'].includes(vector.stimulus.kind),`${vector.id} stimulus kind`);
    const familyStimuli=FAMILY_STIMULI[vector.family],allowedOperations=familyStimuli?.[vector.stimulus.kind];assert.ok(allowedOperations,`${vector.id} ${vector.family} may not use ${vector.stimulus.kind}`);assert.ok(allowedOperations.includes(vector.stimulus.operation),`${vector.id} invalid ${vector.family} operation ${vector.stimulus.operation}`);
    if(vector.stimulus.kind==='canonical_request'){
      const request=JSON.parse(requestBytes.toString('utf8'));
      assert.equal(canonical(request),requestBytes.toString('utf8'),`${vector.id} request is not exact CJ`);
      assert.equal('case_id' in request,false,`${vector.id} embeds case_id`);
      assert.equal('input' in request,false,`${vector.id} embeds Registry prose`);
      assert.equal('operation' in request,false,`${vector.id} operation belongs outside tool input`);
    }else{
      assert.doesNotMatch(requestBytes.toString('utf8'),/"(?:case_id|input|operation)"\s*:/,`${vector.id} raw transport embeds a generic request shell`);
    }
    assertResponseDigests(vector.expected.response,vector.id);
    assertStateDigests(vector);
  }
});

