    if(value.tag==='GKOS-P6-DC06-FIXTURE-PROTECTION-V1')assert.deepEqual(value.preimage.acl,declaredSet(value.preimage.acl.map(canonical)).map(JSON.parse),`${vector.id} ACL declared-set normalization`);
