  for(const vector of vectors){const proofs=new Map();for(const entry of vector.initial_state.oracles.digest_outputs){let value;try{value=JSON.parse(entry.canonical_value);}catch{continue;}if(!value?.tag)continue;if(!proofs.has(value.tag))proofs.set(value.tag,new Set());proofs.get(value.tag).add(value.output);}const requireProof=(tag,output,label)=>assert.ok(proofs.get(tag)?.has(output),`${vector.id} lacks ${tag} proof for ${label}`);const physical=new Map([...vector.initial_state.physical_ledger,...vector.expected.physical_ledger].map((x)=>[canonical(x),x]));for(const entry of physical.values())if(entry.presence){for(const [field,tag] of [['path_binding_digest','GKOS-P6-DC06-FIXTURE-PATH-BINDING-V1'],['physical_identity_digest','GKOS-P6-DC06-FIXTURE-PHYSICAL-IDENTITY-V1'],['owner_digest','GKOS-P6-DC06-FIXTURE-OWNER-V1'],['protection_digest','GKOS-P6-DC06-FIXTURE-PROTECTION-V1'],['content_digest','GKOS-P6-DC06-FIXTURE-CONTENT-ORACLE-V1']])requireProof(tag,entry[field],`${entry.locator_key}.${field}`);}for(const row of [...rowsOf(vector.initial_state.durable_ledger,'rate_bucket'),...rowsOf(vector.expected.durable_ledger,'rate_bucket')])requireProof('GKOS-P6-DC06-FIXTURE-RATE-BUCKET-V1',rowFields(row).bucket_id,`rate bucket ${row.primary_key}`);for(const value of new Set(Buffer.from(vector.stimulus.request_bytes_hex,'hex').toString('utf8').match(/gk(?:cur|rec|scp)1_[A-Za-z0-9_-]+/g)??[])){if(value.startsWith('gkcur1_')&&['CURSOR-ALIAS-001','CURSOR-ALIAS-002'].includes(vector.id))continue;requireProof(value.startsWith('gkcur1_')?'GKOS-P6-DC06-FIXTURE-CURSOR-V1':'GKOS-P6-DC06-FIXTURE-REFERENCE-V1',value,`wire identifier ${value}`);}}
