  const encodingCollisions=collision.filter((x)=>x.id.startsWith('COLLISION-ENCODING-'));assert.equal(encodingCollisions.length,12);for(const vector of encodingCollisions)assert.equal(vector.initial_state.oracles.entropy.programmed.length,0,`${vector.id} must not call entropy`);for(const id of ['COLLISION-ID-IDEMPOTENCY-001','IDEMPOTENCY-REQUEST-CONFLICT-001'])assert.equal(byId.get(id).initial_state.oracles.entropy.programmed.length,0,`${id} must not call entropy`);
