    let match;if(vector.id==='ACTIVITY-BYTE-LIMIT-001')assert.equal(proof.canonical_byte_length,8192);else if(vector.id==='ACTIVITY-BYTE-LIMIT-002')assert.equal(proof.canonical_byte_length,8193);else if((match=/^ACTIVITY-CACHE-(\d{3})$/.exec(vector.id))){const value=acceptedCache[match[1]]??'arbitrary_string';assert.equal(proof.metadata.cache_outcome,value);assert.equal(success,Boolean(acceptedCache[match[1]]));}else if(vector.id==='ACTIVITY-CONTENT-001'){assert.equal(success,false);assert.ok(Object.values(proof.metadata).some((x)=>typeof x==='string'&&/path|sql|stack|credential|subject|user/i.test(x)),'content-negative metadata lacks named sensitive classes');}else if((match=/^ACTIVITY-INTEGER-(\d{3})(?:-(?:ITEM-COUNT|OUTPUT-BYTES|RESULT-COUNT))?$/.exec(vector.id))){const field=integerField(vector.id);assert.equal(proof.metadata[field],integerValue[match[1]]);assert.equal(success,['001','002'].includes(match[1]));}else if(vector.id==='ACTIVITY-KEY-LIMIT-001')assert.equal(proof.key_count,16);else if(vector.id==='ACTIVITY-KEY-LIMIT-002'){assert.equal(proof.key_count,17);assert.equal(success,false);}else if((match=/^ACTIVITY-SIDE-EFFECT-(\d{3})$/.exec(vector.id))){const value=acceptedSide[match[1]]??'arbitrary_string';assert.equal(proof.metadata.side_effect_class,value);assert.equal(success,Boolean(acceptedSide[match[1]]));}else if(vector.id==='ACTIVITY-UNKNOWN-KEY-001'){assert.equal(success,false);const allowed=new Set(['cache_outcome','input_bytes','item_count','output_bytes','result_count','side_effect_class']);assert.ok(Object.keys(proof.metadata).some((x)=>!allowed.has(x)),'unknown-key case has no unknown key');}else assert.fail(`unscanned ACTIVITY vector ${vector.id}`);
